const fs=require('fs'),p=require('path'),c=require('crypto');
const need=(v,m)=>{if(!v)throw Error(m)},fields=['dev','ino','mode','size','mtimeNs','ctimeNs','nlink'];
function readExact(i){const x=i.path;need(p.isAbsolute(x)&&p.normalize(x)===x,'absolute normalized');let a='/';for(const k of x.split('/').filter(Boolean)){a=p.join(a,k);need(!fs.lstatSync(a).isSymbolicLink(),'symlink');}const s=fs.lstatSync(x,{bigint:true});need(s.isFile()&&s.size<=67108864n,'regular cap');if(i.bytes!==undefined)need(s.size===BigInt(i.bytes),'initial size');const same=t=>fields.every(k=>t[k]===s[k]);const fd=fs.openSync(x,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);let b;try{need(same(fs.fstatSync(fd,{bigint:true})),'fd-before');const chunks=[];let n=0,cap=Number(s.size)+1;while(n<cap){const z=Buffer.alloc(Math.min(65536,cap-n)),g=fs.readSync(fd,z,0,z.length,null);if(!g)break;chunks.push(z.subarray(0,g));n+=g;}b=Buffer.concat(chunks);need(b.length===Number(s.size)&&same(fs.fstatSync(fd,{bigint:true})),'fd-after/length');}finally{fs.closeSync(fd);}need(same(fs.lstatSync(x,{bigint:true}))&&fs.realpathSync(x)===x,'path-after');const r={path:x,bytes:b.length,sha256:c.createHash('sha256').update(b).digest('hex')};if(i.sha256!==undefined)need(r.sha256===i.sha256,'hash');return {...r,body:b};}
const simple=r=>({path:r.path,bytes:r.bytes,sha256:r.sha256});

const mode=process.argv[1]||'preseal';
need(mode==='preseal'||mode==='final6','mode');
const dir="/Volumes/AI_DATA/development/det-review-evidence/ri248-native-canonical-companion-of3isoc8";
const names4=['CANONICAL_BINDING.md','COMPANION_ROW.md','HANDOFF.md','SOURCE_REFERENCES.json'].sort();
const names6=[...names4,'AUTHOR_VERIFICATION.json','HANDOFF.json'].sort();
const expected=mode==='preseal'?names4:names6;
need(fs.lstatSync(dir).isDirectory()&&!fs.lstatSync(dir).isSymbolicLink(),'reservation');
need(JSON.stringify(fs.readdirSync(dir).sort())===JSON.stringify(expected),'namespace');
const canonicalAdmin=x=>Array.isArray(x)?x.map(canonicalAdmin):(x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,canonicalAdmin(x[k])])):x);
const equalAdmin=(a,b)=>JSON.stringify(canonicalAdmin(a))===JSON.stringify(canonicalAdmin(b));
const sameId=(a,b)=>['path','bytes','sha256'].every(k=>a[k]===b[k]);
const reads=new Map();
function pinned(i){need(!i.path.endsWith('/CERTIFICATE.json')&&!i.path.endsWith('/check.py'),'no original scientific body/executor');const r=readExact(i);const prior=reads.get(r.path);if(prior)need(sameId(prior,r),'repeated identity');reads.set(r.path,simple(r));return r;}
const current=names4.map(n=>pinned({path:p.join(dir,n)}));
const S=JSON.parse(current.find(r=>p.basename(r.path)==='SOURCE_REFERENCES.json').body.toString('utf8'));
need(S.schema==='ri248-admitted-source-references-v1'&&S.status==='SOURCE_ONLY_AUTHOR_PACKET_FOR_INDEPENDENT_REVIEW','references');
const ass=JSON.parse(pinned(S.assignment).body.toString('utf8'));
need(ass.schema==='ri248-native-canonical-companion-assignment-v1'&&ass.status==='ASSIGNED_AFTER_PREDECESSOR_ADJUDICATION','assignment');
need(ass.reservation===dir&&ass.thread==='01a074c4-4b09-76a3-8cb2-0caf116f6b9c','owner/reservation');
need(ass.new_literal_authority===false&&sameId(ass.assignment,S.assignment_text),'no new admission');
pinned(S.assignment_text);
const dec=JSON.parse(pinned(S.accepted_predecessor).body.toString('utf8'));
need(dec.status==='ACCEPT_ACTUAL_SIX_HOOK_WITNESS_AND_NONEXCEPTIONAL_BRANCH_ONLY','accepted predecessor');
const P=JSON.parse(pinned(S.predecessor_references).body.toString('utf8'));
need(S.preserved_boundary_keys.length===15&&JSON.stringify(S.preserved_boundary_keys)===JSON.stringify(P.preserved_boundary_keys),'boundary names');
for(const k of S.preserved_boundary_keys)need(JSON.stringify(S.preserved_boundaries[k])===JSON.stringify(P.preserved_boundaries[k]),'unchanged boundary '+k);
const paths=S.direct_sources.map(x=>x.identity.path);
need(paths.length===102&&new Set(paths).size===paths.length,'direct source count/unique');
for(const row of S.direct_sources){need(['accepted-analytic-text','administrative-reference','opaque-historical-support'].includes(row.access),'access policy');pinned(row.identity);}
for(const row of P.direct_sources)need(S.direct_sources.some(x=>sameId(x.identity,row.identity)),'inherited source');
const closed=S.closed_RI246_literal_exception_by_reference;
need(closed.closed===true&&closed.new_body_read_or_hash===false&&sameId(closed.reference,S.predecessor_references)&&closed.field==='current_literal_exception','closed old exception');
const proposal=S.proposed_acquisition;
need(proposal.status==='DESIGN_ONLY_NOT_ADMITTED'&&proposal.source_body_opened===false&&proposal.source_hash_freshly_computed===false,'proposed-only source');
need(!paths.includes(proposal.expected_source_identity.path),'proposed body not direct source');
need(proposal.source_indices_resolved===false&&proposal.canonical_values_resolved===false&&proposal.index_and_sparse_schema_evidence_still_required===true,'binding gaps retained');
need(S.current_scope.manual_mathematical_reasoning===true&&S.current_scope.candidate_source_lstat_only===true&&S.current_scope.administrative_manifest_inspected_without_descendant_reads===true,'manual scope');
for(const k of ['automatic_scientific_arithmetic','scientific_body_read','scientific_body_hash','scientific_JSON_decoded','new_coordinate_read','full_vector_instantiated','H_or_z_reconstructed','new_amplitude','subject_execution','measurement_access','RET_access','repository_changes','git_or_index_operations','source_admission_issued','successor_assigned','original_RI41_RI197_RI216_RI231_RI246_exceptions_renewed'])need(S.current_scope[k]===false,'scope '+k);
need(S.current_scope.qualification_credit===0,'credit');
for(const k of ['failed_shell_commands','failed_orchestration_attempts','rejected_patches','clipped_displays'])need(S.diagnostics[k]===0,'current diagnostics');
need(equalAdmin(S.diagnostics.predecessor_diagnostics,P.diagnostics),'prior diagnostics retained');
const prev=JSON.parse(pinned(S.predecessor_handoff).body.toString('utf8'));
need(prev.schema==='ri246-native-hook-literals-handoff-v1','predecessor');
for(const i of prev.files)pinned(i);
const prevNames=fs.readdirSync(p.dirname(S.predecessor_handoff.path)).sort();
need(equalAdmin(prevNames,['AUTHOR_VERIFICATION.json','HANDOFF.json','HANDOFF.md','HOOK_BRANCH_CONSEQUENCE.md','SIX_HOOK_WITNESS.md','SOURCE_REFERENCES.json'].sort()),'predecessor namespace');
if(mode==='final6'){
const H=JSON.parse(pinned({path:p.join(dir,'HANDOFF.json')}).body.toString('utf8'));
need(H.schema==='ri248-native-canonical-companion-handoff-v1'&&H.status==='SEALED_SOURCE_ONLY_AUTHOR_RESULT_PENDING_INDEPENDENT_REVIEW','handoff');
need(H.reservation===dir&&H.files.length===5&&equalAdmin(H.namespace,names6),'handoff files');
for(const i of H.files)pinned(i);
const ai=H.files.find(x=>p.basename(x.path)==='AUTHOR_VERIFICATION.json');need(ai,'author pin');
const A=JSON.parse(pinned(ai).body.toString('utf8'));
need(A.schema==='ri248-author-verification-v1'&&A.independent_acceptance===false&&A.scientific_execution===false,'author scope');
need(equalAdmin(A.payloads,current.map(simple)),'four payload pins');
need(equalAdmin(A.diagnostics,S.diagnostics)&&equalAdmin(H.diagnostics,S.diagnostics),'diagnostics consistency');
need(H.actual_full_normalized_witness===false&&H.actual_signed_inconsistency===false&&H.canonical_Cb_resolved===false&&H.actual_kappa_gap_resolved===false,'actual decision open');
need(H.complete_original_recovery_retained===true&&H.accepted_full_system_iff_retained===true&&H.inherited_zero_hook_branch_retained===true,'original system retained');
need(H.successor_assigned===false&&H.qualification_credit===0,'handoff boundary');
for(const i of current.map(simple))need(H.files.some(j=>sameId(i,j)),'handoff payloads');
}
for(const i of reads.values())readExact(i);
console.log(JSON.stringify({
schema:'ri248-metadata-check-result-v1',mode,exit_intent:0,
scope:'Compact complete administrative result. File identities, metadata declarations, namespaces and preserved boundaries only; no scientific body, proof arithmetic or scientific execution.',
direct_sources:S.direct_sources.length,direct_bytes:S.direct_sources.reduce((n,x)=>n+x.identity.bytes,0),
whole_identities:reads.size,preserved_boundaries:S.preserved_boundary_keys.length,
inherited_manifest_sources_by_reference:S.preserved_boundaries.inherited_manifest_by_reference.selected_paths,
original_scientific_body_read:false,original_scientific_body_hash:false,scientific_JSON_decoded:false,proof_arithmetic:false,scientific_execution:false,
closed_RI246_authority_retained:true,proposed_source_not_opened:true,
current_namespace:expected,predecessor_namespace:prevNames,
current_identities:[...reads.values()].filter(x=>p.dirname(x.path)===dir)
}));
